class CreateJobDialog{constructor($scope,$mdDialog,DispatchData,toastrService,loadingService,$http,$document,staffId){this.$scope=$scope;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.$http=$http;this.toastrService=toastrService;this.loadingService=loadingService;this.$document=$document;this.staffId=staffId;this.jobForm=$scope.jobForm;this.fromAddressSearchText="";this.toAddressSearchText="";this.searchClientText="";this.selectedClient=null;this.selectedFromAddress=null;this.selectedToAddress=null;this.jobDate=new Date;this.jobDate.setDate(this.jobDate.getDate()+1);this.job={clientID:"",deliverToContact:"",fromAddress:"",toAddress:"",date:"",fromContactName:"",deliveryNotes:"",pickupNotes:"",van:false,truck:false,pedal:false,attention:false,vanOK:false,reprice:false,void:false,done:false,charge:0}}async clientSearchAutocomplete(searchTerm){const url="/home/ActiveClients";try{return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async addressSearchAutocomplete(searchText){try{const suggestions=await this.DispatchData.autocompleteAddressSearch(searchText);return this.transformSuggestions(suggestions)}catch(error){this.toastrService.showErrorToast(error.message)}}transformSuggestions(data){return data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}))}async submit(event,job){try{if(!this.jobForm.$valid){this.$mdDialog.show(this.$mdDialog.alert().parent(angular.element(this.$document.body)).clickOutsideToClose(true).title("Required Fields").textContent("Please complete all the required fields.").ariaLabel("Not all required fields are completed").ok("Got it!").targetEvent(event));return}job.clientID=this.selectedClient.id;job.fromAddress=this.selectedFromAddress.text;job.toAddress=this.selectedToAddress.text;job.date=this.jobDate.toISOString();const response=await this.createJob(job);const newJobId=response.data;this.toastrService.showSuccessToast("New Job Created Successfully");this.$mdDialog.hide(newJobId)}catch(error){this.toastrService.showErrorToast(error.message)}}async createJob(job){try{const url="job/QuickCreateJob/";const callData={job:job,staffId:this.staffId};return await this.$http.post(url,callData,{headers:{"Content-Type":"application/json"}})}catch(error){this.toastrService.showErrorToast(error.message)}}cancel(){this.$mdDialog.cancel()}}